   702  static ALWAYS_INLINE void parse_connection_header(struct lwan_request *request)
   703  {
   704      struct lwan_request_parser_helper *helper = request->helper;
   705      bool has_keep_alive = false;
   706      bool has_close = false;
   707
   708      if (!helper->connection.len)
   709          goto out;
   710
   711      for (const char *p = helper->connection.value; *p; p++) {
   712          STRING_SWITCH_L(p) {
   713          case MULTICHAR_CONSTANT_L('k','e','e','p'):
   714          case MULTICHAR_CONSTANT_L(' ', 'k','e','e'):
   715              has_keep_alive = true;
   716              break;
   717          case MULTICHAR_CONSTANT_L('c','l','o','s'):
   718          case MULTICHAR_CONSTANT_L(' ', 'c','l','o'):
   719              has_close = true;
   720              break;
   721          case MULTICHAR_CONSTANT_L('u','p','g','r'):
   722          case MULTICHAR_CONSTANT_L(' ', 'u','p','g'):
   723              request->conn->flags |= CONN_IS_UPGRADE;
   724              break;
   725          }
   726
   727          if (!(p = strchr(p, ',')))
   728              break;
   729      }
   730
   731  out:
   732      if (LIKELY(!(request->flags & REQUEST_IS_HTTP_1_0)))
   733          has_keep_alive = !has_close;
   734
   735      if (has_keep_alive)
   736          request->conn->flags |= CONN_KEEP_ALIVE;
   737      else
   738          request->conn->flags &= ~CONN_KEEP_ALIVE;
   739  }
